				cause: "Kết nối điều khiển (MQTT 8883) liên tục ngắt kết nối và kết nối lại - thường là đường dẫn mạng yếu hoặc cổng bị chặn một phần.",
				fix: "Kiểm tra tín hiệu Wi-Fi trên máy in, ưu tiên kết nối có dây và đảm bảo cổng 8883 có thể truy cập được một cách đáng tin cậy.",
